def metrics(tp, fp, fn, tn):
    def div(a, b):
        return a / b if b else 0.0
    total = tp + fp + fn + tn
    p = div(tp, tp + fp)
    r = div(tp, tp + fn)
    f1 = div(2 * p * r, p + r)
    return {'accuracy': round(div(tp + tn, total), 4), 'precision': round(p, 4), 'recall': round(r, 4), 'f1': round(f1, 4)}

