def threshold_for_recall(scores, labels, target):
    positives = sum(labels)
    if positives == 0:
        return None
    for t in sorted(set(scores), reverse=True):
        tp = sum(1 for s, y in zip(scores, labels) if s >= t and y == 1)
        if tp / positives >= target:
            return t
    return None

